:root {
    --primary-color: #111111;
    --secondary-color: #f4f4f4;
    --accent-color: #d32f2f; /* For deals/sale */
    --text-color: #333333;
    --text-light: #666666;
    --bg-color: #ffffff;
    --focus-ring: 3px solid #005fcc;
    --font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, Helvetica, Arial, sans-serif;
    --transition: all 0.3s ease;
}

* {
    box-sizing: border-box;
    margin: 0;
    padding: 0;
}

body {
    font-family: var(--font-family);
    color: var(--text-color);
    background-color: var(--bg-color);
    line-height: 1.6;
}

a {
    color: var(--primary-color);
    text-decoration: none;
}

a:hover {
    text-decoration: underline;
}

/* Focus styles for accessibility */
a:focus-visible, button:focus-visible, input:focus-visible {
    outline: var(--focus-ring);
    outline-offset: 2px;
}

/* Skip link */
.skip-link {
    background: var(--primary-color);
    color: white;
    padding: 12px 24px;
    z-index: 100;
    font-weight: bold;
    display: block;
}

.skip-link:not(:focus):not(:active) {
    clip: rect(0 0 0 0);
    clip-path: inset(50%);
    height: 1px;
    overflow: hidden;
    position: absolute;
    white-space: nowrap;
    width: 1px;
}

/* Container */
.container {
    max-width: 1200px;
    margin: 0 auto;
    padding: 0 20px;
}

/* Header */
.site-header {
    border-bottom: 1px solid #eaeaea;
    position: sticky;
    top: 0;
    background: var(--bg-color);
    z-index: 50;
}

.header-inner {
    display: flex;
    justify-content: space-between;
    align-items: center;
    height: 70px;
}

.logo a {
    font-size: 1.5rem;
    font-weight: bold;
    letter-spacing: 1px;
    text-transform: uppercase;
}

.logo a:hover {
    text-decoration: none;
}

/* Navigation */
.main-nav {
    display: flex;
    align-items: center;
}

.nav-list {
    list-style: none;
    display: flex;
    gap: 24px;
}

.nav-list a {
    font-weight: 500;
    padding: 8px 0;
}

.mobile-menu-toggle {
    display: none;
    background: none;
    border: none;
    cursor: pointer;
    padding: 8px;
    color: var(--primary-color);
}

/* Header Actions */
.header-actions {
    display: flex;
    gap: 16px;
}

.action-btn {
    background: none;
    border: none;
    cursor: pointer;
    position: relative;
    padding: 8px;
    display: flex;
    align-items: center;
    justify-content: center;
    color: var(--primary-color);
}

.cart-badge {
    position: absolute;
    top: 0;
    right: 0;
    background: var(--accent-color);
    color: white;
    font-size: 0.75rem;
    font-weight: bold;
    width: 18px;
    height: 18px;
    border-radius: 50%;
    display: flex;
    align-items: center;
    justify-content: center;
}

/* Buttons */
.btn {
    display: inline-block;
    padding: 12px 24px;
    font-weight: 600;
    text-align: center;
    border-radius: 4px;
    cursor: pointer;
    transition: var(--transition);
    border: 2px solid transparent;
}

.btn-primary {
    background: var(--primary-color);
    color: white;
}

.btn-primary:hover, .btn-primary:focus-visible {
    background: #333;
    text-decoration: none;
}

.btn-secondary {
    background: transparent;
    color: var(--primary-color);
    border-color: var(--primary-color);
}

.btn-secondary:hover, .btn-secondary:focus-visible {
    background: var(--primary-color);
    color: white;
    text-decoration: none;
}

/* Sections */
section {
    padding: 60px 0;
}

section h2 {
    font-size: 2rem;
    margin-bottom: 32px;
    text-align: center;
}

/* Hero Section */
.hero {
    background-color: var(--secondary-color);
    padding: 100px 0;
    text-align: center;
}

.hero-content h1 {
    font-size: 3rem;
    margin-bottom: 16px;
    line-height: 1.2;
}

.hero-content p {
    font-size: 1.25rem;
    color: var(--text-light);
    margin-bottom: 32px;
    max-width: 600px;
    margin-left: auto;
    margin-right: auto;
}

/* Deals Section */
.deals {
    padding-top: 20px;
}

.deals-banner {
    background: var(--accent-color);
    color: white;
    padding: 40px;
    text-align: center;
    border-radius: 8px;
}

.deals-banner h2 {
    color: white;
    margin-bottom: 8px;
}

.deals-banner p {
    font-size: 1.25rem;
    margin-bottom: 24px;
}

.deals-banner .btn-secondary {
    border-color: white;
    color: white;
}

.deals-banner .btn-secondary:hover {
    background: white;
    color: var(--accent-color);
}

/* Featured Products */
.product-grid {
    list-style: none;
    display: grid;
    grid-template-columns: repeat(auto-fill, minmax(250px, 1fr));
    gap: 32px;
}

.product-card {
    display: flex;
